export class RecursiveScaffolder {
  constructor() {
    this.taskGraph = {};
    this.feedbackHandlers = [];
  }

  addTask(taskId, dependencies = []) {
    this.taskGraph[taskId] = { dependencies, status: 'pending' };
  }

  updateTaskStatus(taskId, status) {
    if (this.taskGraph[taskId]) {
      this.taskGraph[taskId].status = status;
      this.evaluateGraph();
    }
  }

  registerFeedbackHandler(handler) {
    this.feedbackHandlers.push(handler);
  }

  evaluateGraph() {
    Object.keys(this.taskGraph).forEach(taskId => {
      const task = this.taskGraph[taskId];
      if (task.status === 'pending') {
        const allDepsCompleted = task.dependencies.every(
          dep => this.taskGraph[dep]?.status === 'completed'
        );
        if (allDepsCompleted) {
          this.executeTask(taskId);
        }
      }
    });
  }

  executeTask(taskId) {
    console.log(`Executing task: ${taskId}`);
    this.taskGraph[taskId].status = 'completed';
    this.feedbackHandlers.forEach(handler => handler(taskId));
  }
}

// Example usage
const scaffolder = new RecursiveScaffolder();
scaffolder.addTask('task1');
scaffolder.addTask('task2', ['task1']);
scaffolder.registerFeedbackHandler(taskId => {
  console.log(`Feedback received for ${taskId}`);
});
scaffolder.updateTaskStatus('task1', 'completed');